{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Dana Reyes"
    },
    {
      "id": "get_sam_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Sam Okafor"
    },
    {
      "id": "get_next_week_dates",
      "kind": "list",
      "source": "calendar",
      "filter": "date_range: next_week"
    },
    {
      "id": "generate_hourly_slots",
      "kind": "list",
      "source": "calendar",
      "filter": "time_slots: hourly, next_week"
    },
    {
      "id": "check_dana_free",
      "kind": "loop_over_items",
      "over": "generate_hourly_slots",
      "steps": [
        {
          "id": "check_dana_conflict",
          "kind": "lookup_via_agent",
          "agent": "calendar",
          "find": "conflicts for Dana Reyes in slot"
        },
        {
          "id": "is_dana_free",
          "kind": "classify",
          "enum": ["free", "busy"],
          "question": "Is Dana Reyes free in this slot based on conflicts?"
        }
      ],
      "output": "dana_free_slots"
    },
    {
      "id": "check_sam_free",
      "kind": "loop_over_items",
      "over": "generate_hourly_slots",
      "steps": [
        {
          "id": "check_sam_conflict",
          "kind": "lookup_via_agent",
          "agent": "calendar",
          "find": "conflicts for Sam Okafor in slot"
        },
        {
          "id": "is_sam_free",
          "kind": "classify",
          "enum": ["free", "busy"],
          "question": "Is Sam Okafor free in this slot based on conflicts?"
        }
      ],
      "output": "sam_free_slots"
    },
    {
      "id": "find_shared_slot",
      "kind": "loop_over_items",
      "over": "dana_free_slots",
      "steps": [
        {
          "id": "check_sam_match",
          "kind": "classify",
          "enum": ["match", "no_match"],
          "question": "Is Sam Okafor also free in this specific slot?"
        }
      ],
      "output": "shared_free_slots"
    },
    {
      "id": "select_proposal_slot",
      "kind": "classify",
      "enum": ["first_available", "none"],
      "question": "Select the first available shared slot or indicate none found."
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a brief message proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 50
    },
    {
      "id": "check_coverage",
      "kind": "check_coverage",
      "rule": "The output proposal must reference exactly one time slot that is free for both Dana Reyes and Sam Okafor."
    }
  ],
  "output": "draft_proposal"
}

